INSERT INTO `countrytours` VALUES (15,6,'From Kathmandu to Pokhara: Enchanting Nepal Getaway - FAQ','{\"time\":1764311564946,\"blocks\":[{\"id\":\"FmwUQhdsvv\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Routing:</b>Kathmandu-Nagarkot-Chitwan-Pokhara-Kathmandu<br><br>\"}},{\"id\":\"RU84hOCNEU\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Duration:</b> 07Nights 08 Days<br><br>\"}},{\"id\":\"JCHs4Ip5KD\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Tour Overview:</b> Uncover the beauty of Nepal with a scenic route. Glide through the beauty of Nagarkot, witness the sunrise over the Himalayas, go on an exotic wildlife safari in Chitwan, and unwind in the romantic beauty of Pokhara. With every stop, cherish the warmth &amp; charm each place offers. During these 08 days of exploration, let your heart be filled with the true essence of Nepal.\"}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,'{\"time\":1764311564947,\"blocks\":[{\"id\":\"E5SUTMLljN\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"01 Night Accommodation in Kathmandu on BB basis (Breakfast Only)\",\"meta\":{},\"items\":[]},{\"content\":\"01 Night Accommodation in Nagarkot on BB basis (Breakfast Only),\",\"meta\":{},\"items\":[]},{\"content\":\"02 nightsâ€™ accommodation in Chitwan on AP basis with all jungle activities and national park fees (breakfast/lunch and dinner)\",\"meta\":{},\"items\":[]},{\"content\":\"02 Nightsâ€™ Accommodation in Pokhra on BB basis (Breakfast Only)\",\"meta\":{},\"items\":[]},{\"content\":\"01 Night Accommodation in Kathmandu on a BB basis (Breakfast Only)\",\"meta\":{},\"items\":[]},{\"content\":\"Arrival and departure airport transfers by private AC vehicle,\",\"meta\":{},\"items\":[]},{\"content\":\"Sightseeing tours in all places as per the program mentioned above by private AC vehicle\",\"meta\":{},\"items\":[]},{\"content\":\"English-speaking guide in Kathmandu during sightseeing with Nagarkot excursion.\",\"meta\":{},\"items\":[]},{\"content\":\"English-speaking guide in Pokhara during sightseeing,\",\"meta\":{},\"items\":[]},{\"content\":\"English-speaking naturalist in Chitwan while doing activities in Chitwan,\",\"meta\":{},\"items\":[]},{\"content\":\"Transportation from Kathmandu-Nagarkot-Chitwan-Pokhara-Kathmandu as per the program by private vehicle with driver only\",\"meta\":{},\"items\":[]},{\"content\":\"Entrance fees at the places of visit during sightseeing for all places in Kathmandu-Pokhara-Nagarkot.\",\"meta\":{},\"items\":[]},{\"content\":\"One-hour boat ride in Fewa Lake in Pokhara, all applicable government taxes.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,NULL,'{\"time\":1764311564947,\"blocks\":[{\"id\":\"mLRpiRm0uc\",\"type\":\"paragraph\",\"data\":{\"text\":\"Not Available\"}}],\"version\":\"2.31.0-rc.7\"}','{\"time\":1764311564947,\"blocks\":[{\"id\":\"LseKWtWGzm\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"Any air and train fare.\",\"meta\":{},\"items\":[]},{\"content\":\"Lunch and dinner except as mentioned in the inclusion.\",\"meta\":{},\"items\":[]},{\"content\":\"Tips for drivers.\",\"meta\":{},\"items\":[]},{\"content\":\"Liability for change in itinerary due to reasons beyond our control, like change in schedule.\",\"meta\":{},\"items\":[]},{\"content\":\"Cancellation of flights/trains/political disturbances, natural phenomena, etc.\",\"meta\":{},\"items\":[]},{\"content\":\"Any other item not specified in the package inclusions.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}'),(16,7,'Sun, Sand & City Vibes: 10 Days of Thailand Escape - FAQ','{\"time\":1763396066859,\"blocks\":[{\"id\":\"VQb2uAccBi\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Routing:</b> Phuket-Krabi-Bangkok\"}},{\"id\":\"iEOiVrVGtu\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Duration:</b> 09Nights 10 Days\"}},{\"id\":\"uxyLNCmra_\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Tour Overview:</b> TrippyJiffy brings you the story of Sun, Sands &amp; City Vibes, 10 days of experiencing the best of Thailand, from pristine beaches and tropical adventures to vibrant city life and cultural treasures. Soak yourself in the scenic beauty with thrilling wildlife encounters. Discover Krabi\'s untouched natural beauty and conclude your journey in Bangkok, the heart of Thailand, home of majestic temples and bustling markets, making for a perfect finale to this unforgettable journey. This itinerary is perfectly curated, making sure that it gives you the blend of leisure, excitement, and rich cultural experience in every step.\"}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,'{\"time\":1763396066859,\"blocks\":[{\"id\":\"pjUFb4L0gK\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"Private vehicle for transfers and sightseeing\",\"meta\":{},\"items\":[]},{\"content\":\"ENGLISH-SPEAKING GUIDE AT ALL PLACES\",\"meta\":{},\"items\":[]},{\"content\":\"500 ML water bottle per person per day\",\"meta\":{},\"items\":[]},{\"content\":\"Road taxes, parking fees, fuel charges, and interstate taxes.\",\"meta\":{},\"items\":[]},{\"content\":\"Daily buffet breakfast at all hotels and a representative for assistance on all arrival and departure transfers.\",\"meta\":{},\"items\":[]},{\"content\":\"04 nights\' stay in Phuket.\",\"meta\":{},\"items\":[]},{\"content\":\"02 Nights Stay in Krabi.\",\"meta\":{},\"items\":[]},{\"content\":\"03 nights\' stay in Bangkok.\",\"meta\":{},\"items\":[]},{\"content\":\"Phi Phi Island tour by sharing a speedboat with lunch.\",\"meta\":{},\"items\":[]},{\"content\":\"Island tour by private longtail boat with lunch\",\"meta\":{},\"items\":[]},{\"content\":\"Chao Phraya Dinner on Cruise on a PVT basis.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,NULL,'{\"time\":1763396066860,\"blocks\":[{\"id\":\"6D_n1x48UT\",\"type\":\"paragraph\",\"data\":{\"text\":\"Not Available\"}}],\"version\":\"2.31.0-rc.7\"}','{\"time\":1763396066860,\"blocks\":[{\"id\":\"WURXXIkUMy\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"Airfare and visa charges.\",\"meta\":{},\"items\":[]},{\"content\":\"All Entrance Fees.\",\"meta\":{},\"items\":[]},{\"content\":\"Boat hires, beverages (all types), lunch, dinner, and any meals other than specified above, and a la carte orders at restaurants and hotels.\",\"meta\":{},\"items\":[]},{\"content\":\"Early check-in / late check-out, personal expenses such as any kind of laundry, telephone calls, room service, etc.\",\"meta\":{},\"items\":[]},{\"content\":\"Transport and guide services during times at leisure as indicated on the itinerary.\",\"meta\":{},\"items\":[]},{\"content\":\"Site Guide services at places of interest, photographic and video permits\",\"meta\":{},\"items\":[]},{\"content\":\"All tips and gratuities, insurance, medical or any other claims, and expenses incurred during the emergency or evacuation.\",\"meta\":{},\"items\":[]},{\"content\":\"All bank charges when receiving payments and refunds of unutilized services.\",\"meta\":{},\"items\":[]},{\"content\":\"Services other than specified above.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}'),(17,8,'Elite Dubai Getawayâ€”5 Days of Arabian Holiday - FAQ','{\"time\":1763679919591,\"blocks\":[{\"id\":\"eg8PZ56TkA\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Routing:</b> Dubai-Abu Dhabi<br><b><br>Duration:</b> 04 Nights &amp; 05 Days<br><b><br>Tour overview:</b> Discover the magic of Arabian culture only with TrippyJiffyâ€™s 5 days of elite Dubai getaways. Cruising through illuminated waterfronts and iconic landmarks and thrilling adventures of the desert safari and majestic beauty of the Grand Mosque. Explore the breathtaking skyline of Dubai from the heights of Burj Khalifa. This tour is a perfect blend of luxury, culture, and Arabian nights.\"}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,'{\"time\":1763679919592,\"blocks\":[{\"id\":\"5mQqC3gzY5\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"04 Nights Accommodation\",\"meta\":{},\"items\":[]},{\"content\":\"Daily buffet breakfast.\",\"meta\":{},\"items\":[]},{\"content\":\"Abu Dhabi City Tour â€“ Sheikh Zayed Grand Mosque &amp; BAPS Hindu Temple\",\"meta\":{},\"items\":[]},{\"content\":\"Half-Day Dubai City Tour\",\"meta\":{},\"items\":[]},{\"content\":\"Dhow Cruise with Dinner\",\"meta\":{},\"items\":[]},{\"content\":\"Desert Safari with BBQ Dinner &amp; Live Performances.\",\"meta\":{},\"items\":[]},{\"content\":\"Private Airport Transfers.\",\"meta\":{},\"items\":[]},{\"content\":\"Sightseeing on an SIC basis.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,NULL,'{\"time\":1763679919592,\"blocks\":[{\"id\":\"c6ctiYwYZB\",\"type\":\"paragraph\",\"data\":{\"text\":\"Not Available\"}}],\"version\":\"2.31.0-rc.7\"}','{\"time\":1763679919592,\"blocks\":[{\"id\":\"s6lCV-rCej\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"Airfare and visa charges\",\"meta\":{},\"items\":[]},{\"content\":\"&nbsp;All Entrance Fees / Boat Hires.\",\"meta\":{},\"items\":[]},{\"content\":\"&nbsp;Beverages (all types), lunch, dinner, and any meals other than specified above, and a la carte orders at restaurants and hotels.\",\"meta\":{},\"items\":[]},{\"content\":\"&nbsp;Early check-in / late check-out, personal expenses such as any kind of laundry, telephone calls, room service, etc.\",\"meta\":{},\"items\":[]},{\"content\":\"Transport and guide services during times at leisure as indicated on the itinerary\",\"meta\":{},\"items\":[]},{\"content\":\"Site Guide services at places of interest.\",\"meta\":{},\"items\":[]},{\"content\":\"Photographic and video permits.\",\"meta\":{},\"items\":[]},{\"content\":\"All tips and gratuities, insurance, medical, or any other claims.\",\"meta\":{},\"items\":[]},{\"content\":\"Expenses incurred during the emergency or evacuation\",\"meta\":{},\"items\":[]},{\"content\":\"All bank charges when receiving payments.\",\"meta\":{},\"items\":[]},{\"content\":\"Refund of unutilized services.\",\"meta\":{},\"items\":[]},{\"content\":\"Services other than specified above.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}');
