INSERT INTO `landing_page` VALUES (1,'golden-triangle','Golden Triangle Tour','{\"seo\": {\"title\": \"Golden Triangle Tour | TrippyJiffy\", \"description\": \"Explore Delhi, Agra, and Jaipur with a curated Golden Triangle tour. Custom itineraries, premium stays, and seamless transfers.\"}, \"faqs\": [{\"answer\": \"October to March offers pleasant weather for sightseeing across Delhi, Agra, and Jaipur.\", \"question\": \"What is the best time to visit the Golden Triangle?\"}, {\"answer\": \"Yes. We can adjust duration, hotels, and experiences as per your preferences.\", \"question\": \"Can this tour be customized?\"}, {\"answer\": \"Yes, the Taj Mahal is closed every Friday.\", \"question\": \"Is the Taj Mahal closed on any day?\"}], \"hero\": {\"badge\": \"Limited Slots Â· Personalized Itineraries\", \"image\": \"/api/uploads/Banner2.jpg\", \"title\": \"Golden Triangle Tour\", \"slides\": [\"/api/uploads/Banner2.jpg\", \"/api/uploads/Banner32.webp\", \"/api/uploads/contact.jpg\"], \"ctaPhone\": \"+919870210896\", \"subtitle\": \"Delhi Â· Agra Â· Jaipur â€” a perfectly curated introduction to India\'s royal heritage, iconic monuments, and vibrant bazaars.\", \"ctaPrimary\": \"Get Free Quote\", \"ctaSecondary\": \"Call Now\"}, \"slug\": \"golden-triangle\", \"about\": {\"points\": [\"Guided city tours with cultural insights\", \"Flexible pacing for families and couples\", \"Handpicked stays near key attractions\"], \"heading\": \"About the Golden Triangle\", \"description\": \"The Golden Triangle connects Delhi, Agra, and Jaipur â€” India\'s most iconic circuit for first-time visitors. Expect Mughal marvels, royal palaces, vibrant bazaars, and unforgettable food experiences.\"}, \"intro\": {\"cta\": \"Contact Now\", \"image\": \"/api/uploads/Banner32.webp\", \"eyebrow\": \"Explore, Discover, and Relax\", \"heading\": \"Unforgettable Golden Triangle Tours\", \"description\": \"Embark on a classic journey through Delhi, Agra, and Jaipur. From the Taj Mahal at sunrise to royal palaces and vibrant bazaars, enjoy a perfectly balanced mix of heritage, culture, and comfort with expert guidance throughout.\"}, \"stats\": [{\"label\": \"Ideal Duration\", \"value\": \"6-7 Days\"}, {\"label\": \"Delhi â€¢ Agra â€¢ Jaipur\", \"value\": \"3 Cities\"}, {\"label\": \"Guest Rating\", \"value\": \"4.9â˜…\"}], \"theme\": {\"accent\": \"#1e293b\", \"primary\": \"#f97316\", \"secondary\": \"#0ea5e9\"}, \"title\": \"Golden Triangle Tour\", \"contact\": {\"email\": \"travelqueries@trippyjiffy.com\", \"phones\": [\"+91 98702 10896\", \"+91 85274 54549\"], \"address\": \"Sector 1, Vikas Nagar Lucknow 226022 (India)\"}, \"gallery\": [{\"alt\": \"Delhi heritage\", \"src\": \"/api/uploads/Banner!.webp\"}, {\"alt\": \"Agra Taj Mahal\", \"src\": \"/api/uploads/Banner32.webp\"}, {\"alt\": \"Jaipur palaces\", \"src\": \"/api/uploads/contact.jpg\"}, {\"alt\": \"Local markets\", \"src\": \"/api/uploads/l1.jpeg\"}, {\"alt\": \"Cultural experiences\", \"src\": \"/api/uploads/people-doi-pha-tang-against-sky-sunrise_1048944-4357386.jpeg\"}, {\"alt\": \"Royal forts\", \"src\": \"/api/uploads/hiker-looking-mountains-from-great-wall-china-sunset_1048944-9830948.jpeg\"}], \"whyIntro\": {\"images\": [\"/api/uploads/people-doi-pha-tang-against-sky-sunrise_1048944-4357386.jpeg\", \"/api/uploads/contact.jpg\", \"/api/uploads/hiker-looking-mountains-from-great-wall-china-sunset_1048944-9830948.jpeg\"], \"eyebrow\": \"Your India Travel Experts\", \"heading\": \"Why Choose Us\", \"description\": \"We are your trusted partner for Golden Triangle tours, handling every detail from airport pickup to stays and curated experiences.\"}, \"itinerary\": [{\"day\": \"Day 1\", \"title\": \"Arrival in Delhi\", \"description\": \"Airport pickup, check-in, and a relaxed evening at India Gate and Connaught Place.\"}, {\"day\": \"Day 2\", \"title\": \"Old & New Delhi\", \"description\": \"Qutub Minar, Lotus Temple, Jama Masjid, Raj Ghat, and Chandni Chowk.\"}, {\"day\": \"Day 3\", \"title\