  `supplemental_activities` longtext COLLATE utf8mb4_general_ci,
  `exclusions` longtext COLLATE utf8mb4_general_ci,
  PRIMARY KEY (`id`),
  KEY `state_id` (`state_id`),
  CONSTRAINT `tours_chk_1` CHECK (json_valid(`routing`))
