INSERT INTO `tours` VALUES (42,65,'The Royal Escapeâ€”Neemrana Fort Visit - FAQ','{\"time\":1763108622858,\"blocks\":[{\"id\":\"ne1tGLlxXQ\",\"type\":\"paragraph\",\"data\":{\"text\":\"<b>Tour Info: </b>TrippyJiffy brings you â€œThe Royal Escape.â€ With just a 3-hour beautiful scenic drive from Delhi, you enter the Neemrana Fort &amp; Palace. The magnificent beauty of the palace leaves you awestruck. Take a dive into royalty like never before for all the travel lovers hustling in their corporate life. This one-day weekend escape is all your soul is craving. This 15th-century heritage marvel is situated in the Aravalli Hills. This palace is filled with ancient charm, grand courtyards, and panoramic views that transport you to a royal era. From enjoying the royal lunch to Pinterest pictures, this will bring you the wholesome experience.\"}}],\"version\":\"2.31.0-rc.7\"}','2025-11-14 08:22:02','2025-11-14 08:23:42',NULL,NULL,'{\"time\":1763108622859,\"blocks\":[{\"id\":\"sivn5RBjB5\",\"type\":\"list\",\"data\":{\"style\":\"unordered\",\"meta\":{},\"items\":[{\"content\":\"Pick &amp; drop from the airport &amp; train station.\",\"meta\":{},\"items\":[]},{\"content\":\"Lunch at the Fort.\",\"meta\":{},\"items\":[]},{\"content\":\"Cover the sightseeing or places as per the time availability.\",\"meta\":{},\"items\":[]},{\"content\":\"1 packed water bottle of 500 ml per person.\",\"meta\":{},\"items\":[]},{\"content\":\"Driverâ€™s Batta, toll parking, road tax, and fuel charges are all included.\",\"meta\":{},\"items\":[]},{\"content\":\"All taxes and fees are included in the package; any other tax as levied by the government shall be extra.\",\"meta\":{},\"items\":[]}]}}],\"version\":\"2.31.0-rc.7\"}',NULL,NULL,NULL,'{\"time\":1763108622859,\"blocks\":[{\"id\":\"Y-bxje8QK2\",\"type\":\"paragraph\",\"data\":{\"text\":\"Not Available\"}}],\"version\":\"2.31.0-rc.7\"}','{\"time\":1763108622859,\"blocks\":[{\"id\":\"leE3hmqXPq\",\"type\":\"list\",\"data\":{\"style\":\"unorde